-- 关联二级菜单到对应一级菜单（按上面 INSERT 的自增 id 顺序回填）
UPDATE wechat_menu SET parent_id = (SELECT id FROM (SELECT id FROM wechat_menu WHERE account_id=1 AND name='🛍 逛商城') x) WHERE account_id=1 AND name IN ('新品上架','热销榜单');
UPDATE wechat_menu SET parent_id = (SELECT id FROM (SELECT id FROM wechat_menu WHERE account_id=1 AND name='📦 我的订单') x) WHERE account_id=1 AND name IN ('订单查询','物流跟踪','售后申请');
UPDATE wechat_menu SET parent_id = (SELECT id FROM (SELECT id FROM wechat_menu WHERE account_id=2 AND name='📚 课程中心') x) WHERE account_id=2 AND name IN ('少儿编程','初高中提升','成人技能');
UPDATE wechat_menu SET parent_id = (SELECT id FROM (SELECT id FROM wechat_menu WHERE account_id=3 AND name='🪑 在线订座') x) WHERE account_id=3 AND name IN ('查看包间','取消订座');

