-- ---------------------------------------------------------------------------
-- 数据统计
-- ---------------------------------------------------------------------------
SELECT 'sys_user' AS 表名, COUNT(*) AS 记录数 FROM sys_user
UNION ALL SELECT 'wechat_account', COUNT(*) FROM wechat_account
UNION ALL SELECT 'wechat_menu', COUNT(*) FROM wechat_menu
UNION ALL SELECT 'wechat_material', COUNT(*) FROM wechat_material
UNION ALL SELECT 'wechat_reply_rule', COUNT(*) FROM wechat_reply_rule
UNION ALL SELECT 'wechat_message', COUNT(*) FROM wechat_message;

SELECT reply_type AS 回复方式, COUNT(*) AS 条数
FROM wechat_message WHERE reply_type IS NOT NULL GROUP BY reply_type;

SELECT msg_type AS 消息类型, COUNT(*) AS 条数
FROM wechat_message GROUP BY msg_type;
